INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(93914, 'ruRU', '', 'Вступаю в бой!', 24330),
(93915, 'ruRU', '', 'Валите их!', 24330),
(93916, 'ruRU', '', 'Огонь по готовности!', 24330),
(93917, 'ruRU', '', 'Подавить ту цель!', 24330),
(93920, 'ruRU', '', 'Разнесём этих врайкулов!', 24330),
(93933, 'ruRU', '', 'Я отправлю тебя к твоему создателю!', 24330),
(93934, 'ruRU', '', 'Неужели ты так жаждешь встретить своих предков?', 24330),
(93935, 'ruRU', '', 'К несчастью для тебя, твой дух никогда не увидит Акиндун!', 24330),
(93936, 'ruRU', '', 'Обещания наару были пусты. Наш новый господин дарует нам истинную силу!', 24330),
(93937, 'ruRU', '', 'Какой прок от веры, когда Легион дарует такую силу?', 24330),
(93938, 'ruRU', '', 'Глупец! Ты идёшь неверным путём!', 24330),
(93939, 'ruRU', '', 'Легион — это истина. Легион — это сила!', 24330),
(93940, 'ruRU', '', 'В Свете я видел лишь пустоту.', 24330),
(93941, 'ruRU', '', 'Кто смеет мне мешать?', 24330),
(93942, 'ruRU', '', 'Какая досада. Сначала я разберусь с тобой!', 24330),
(93943, 'ruRU', '', 'Katra zil shukil! Ты умрёшь за свою дерзость!', 24330),
(93944, 'ruRU', '', 'Ты унесёшь наши секреты в могилу!', 24330),
(93945, 'ruRU', '', 'Сила Легиона течёт сквозь меня!', 24330),
(93946, 'ruRU', '', 'Они здесь, Терон''гор! Нужно уходить.', 24330),
(93953, 'ruRU', '', 'Прекрати осквернять моих предков!', 24330),
(93954, 'ruRU', '', 'Пора умирать, мерзкий зверь!', 24330),
(93958, 'ruRU', '', 'Жалкий $c, да очистит тебя пламя нового мира!', 24330),
(93967, 'ruRU', '', 'Ты избран вкусить дар хозяина. Выйди вперёд и испей. Обрети силу, в которой тебе так долго отказывали!', 24330),
(93968, 'ruRU', '', 'Их нужно искоренить, прежде чем они завершат свою задачу.', 24330),
(93969, 'ruRU', '', 'Я боюсь за бесчисленные души, которые поглотил этот Кровожад. Его нужно уничтожить!', 24330),
(93995, 'ruRU', '', 'Ради Света, что это ТАКОЕ?', 24330),
(93998, 'ruRU', '', 'Мы залечим раны Тириона достаточно, чтобы вывести его отсюда. Верховный лорд, тебе нужно идти дальше и вернуть Пеплосерд!', 24330),
(94000, 'ruRU', '', 'Железная Орда почти полностью покинула эту местность. Я ожидал более тяжёлого боя за доки.', 24330),
(94001, 'ruRU', '', 'Падальщики Кровавой Пустоши. Нужно разобраться с их главарём и загнать их обратно в джунгли!', 24330),
(94024, 'ruRU', '', 'Если эти мародёры разгуливают на свободе, то где остальная часть Орды Гул''дана? Возможно, они поджидают нас впереди.', 24330),
(94025, 'ruRU', '', 'Чернокнижники и их мерзкая магия! Если Гул''дан добьётся своего, весь этот мир сгорит.', 24330),
(94027, 'ruRU', '', 'Пустынно, если не считать мародёров и чернокнижников. Что прислужники Гул''дана делают так близко от руин портала?', 24330),
(94029, 'ruRU', '', 'Магия Скверны Гул''дана оскверняет даже саму технику Железной Орды! Нам нужно пробиться через этот строй...', 24330),
(94030, 'ruRU', '', '|TInterface\\Icons\\Spell_Shadow_GatherShadows.blp:20|tВас |cFFFF0000|Hspell:179711|h[Осквернили]|h|r, отойдите от союзников!', 24330),
(94031, 'ruRU', '', '|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t|cFFFF0000|Hspell:181498|h[Волна разрушения]|h|r поражает |cFFFF0000|Hspell:179620|h[Кристалл Скверны]|h|r!', 24330),
(94032, 'ruRU', '', '|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t|cFFFF0000|Hspell:182008|h[Скрытая энергия]|h|r $n бурно реагирует, когда тот ступает в |cFFFF0000|Hspell:179582|h[Грохочущую расселину]|h|r!', 24330),
(94033, 'ruRU', '', '|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t|cFFFF0000|Hspell:182008|h[Скрытая энергия]|h|r $n бурно реагирует, когда того поражает |cFFFF0000|Hspell:181498|h[Волна разрушения]|h|r!', 24330),
(94036, 'ruRU', '', '|TInterface\\Icons\\Spell_Shadow_ChillTouch.blp:20|t|cFFFF0000|Hspell:182008|h[Скрытая энергия]|h|r оскверняет вас!', 24330),
(94037, 'ruRU', '', '|TInterface\\Icons\\Spell_Shadow_SeedOfDestruction.blp:20|tВаше |cFFFF0000|Hspell:181508|h[Семя разрушения]|h|r будет испускать |cFFFF0000|Hspell:181498|h[Волны разрушения]|h|r.', 24330),
(94038, 'ruRU', '', '|TInterface\\Icons\\ability_deathwing_grasping_tendrilsgreen.blp:20|t|cFFFF0000|Hspell:179582|h[Грохочущие расселины]|h|r затвердевают в |cFFFF0000|Hspell:179620|h[Кристаллы Скверны]|h|r!', 24330);
